package com.muthumol.player.dummy;
import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import java.util.zip.*;import java.util.regex.*;import org.json.*;import org.drinkless.tdlib.TdApi;
/** Strict title/season/episode matching; async results belong to one selection only. */
final class AutoSubtitles {
 final ChannelSession session;final ExecutorService worker=Executors.newSingleThreadExecutor();volatile int generation;String selected="";
 AutoSubtitles(ChannelSession s){session=s;}
 static boolean subtitle(String name){return name.toLowerCase(Locale.ROOT).matches(".*\\.(srt|ass|ssa|vtt|ttml)$");}
 static MediaTitle title(String name){return MediaTitle.parse(name.replaceFirst("(?i)\\.(srt|ass|ssa|vtt|ttml|zip)$","").replaceAll("(?i)\\b(malayalam|mal|eng|subtitles?|msone)\\b"," "));}
 static int score(Movie movie,String name,String caption){MediaTitle wanted=MediaTitle.parse(movie.title),candidate=title(name);if(MediaTitle.similarity(wanted.name,candidate.name)<.85&&!caption.isEmpty())candidate=title(caption);if(wanted.episodic()!=candidate.episodic())return -1;if(wanted.episodic()&&(wanted.season!=candidate.season||wanted.episode!=candidate.episode))return -1;if(wanted.year>0&&candidate.year>0&&wanted.year!=candidate.year)return -1;double similarity=MediaTitle.similarity(wanted.name,candidate.name);if(similarity<.85)return -1;return (int)(similarity*100)+(name.toLowerCase(Locale.ROOT).matches(".*(malayalam|msone|\\bmal\\b).*")?20:0);}
 static boolean pack(Movie movie,String name){MediaTitle t=MediaTitle.parse(movie.title);if(!name.toLowerCase(Locale.ROOT).endsWith(".zip"))return false;String clean=name.replaceFirst("(?i)\\.zip$","").replaceAll("[._]"," ");Matcher season=Pattern.compile("(?i)\\b(?:s|season\\s*)(\\d{1,2})\\b").matcher(clean);if(t.episodic()){if(!season.find()||Integer.parseInt(season.group(1))!=t.season)return false;clean=clean.substring(0,season.start());}return MediaTitle.similarity(t.name,title(clean).name)>=.85;}
 void find(Movie movie){if(movie.chatId==0||selected.equals(movie.cacheIdentity()))return;android.content.SharedPreferences prefs=session.context.getSharedPreferences("player",0);if(prefs.getBoolean("externalSubtitleOff:"+movie.cacheIdentity(),false)||!prefs.getString("externalSubtitleUri:"+movie.cacheIdentity(),"").isEmpty())return;selected=movie.cacheIdentity();int token=++generation;session.subtitleStatus="Searching subtitles in this chat…";worker.execute(()->{try{Object best=null;String bestName="";int bestScore=-1;long from=0;Set<Long> cursors=new HashSet<>();while(token==generation){TdApi.Object page=session.tg.waitRequest("SearchChatMessages","chatId",movie.chatId,"topicId",null,"query","","senderId",null,"fromMessageId",from,"offset",0,"limit",100,"filter",TelegramBridge.obj("SearchMessagesFilterDocument"));if(page instanceof TdApi.Error)throw new IOException(TelegramBridge.str(page,"message"));Object raw=TelegramBridge.get(page,"messages");if(!(raw instanceof TdApi.Message[]))throw new IOException("Subtitle search unavailable");for(TdApi.Message message:(TdApi.Message[])raw){Object doc=TelegramBridge.get(message.content,"document");String name=TelegramBridge.str(doc,"fileName");int rank=subtitle(name)?score(movie,name,TelegramBridge.str(TelegramBridge.get(message.content,"caption"),"text")):pack(movie,name)?50:-1;if(rank>bestScore){bestScore=rank;best=doc;bestName=name;}}long next=TelegramBridge.num(page,"nextFromMessageId");if(next<=0||next==from||!cursors.add(next))break;from=next;}if(token!=generation)return;byte[] bytes=null;String name=bestName,source="Telegram chat";if(best!=null){Object f=TelegramBridge.get(best,"document");long size=TelegramBridge.num(f,"size");if(size>16*1024*1024)throw new IOException("Subtitle pack exceeds 16 MB");int id=(int)TelegramBridge.num(f,"id");session.tg.download(id,0,size>0?size:16*1024*1024,8);long end=android.os.SystemClock.elapsedRealtime()+30000;while(token==generation&&android.os.SystemClock.elapsedRealtime()<end){TdApi.Object fresh=session.tg.waitRequest("GetFile","fileId",id);Object local=TelegramBridge.get(fresh,"local");if(TelegramBridge.bool(local,"isDownloadingCompleted")){bytes=SmallFileIO.read(new File(TelegramBridge.str(local,"path")),16*1024*1024);break;}TelegramRangeLoader.sleep(100);}if(bytes==null)throw new IOException("Subtitle download timed out");}else{session.subtitleStatus="Checking MSone…";MsoneSubtitles.Result result=MsoneSubtitles.find(movie);if(result==null){session.subtitleStatus="No matching subtitle found";return;}bytes=result.bytes;name=result.name;source="MSone";}
 if(name.toLowerCase(Locale.ROOT).endsWith(".zip")){Packed result=unpack(bytes,movie,name);if(result==null)throw new IOException("No matching episode in subtitle pack");bytes=result.bytes;name=result.name;}if(bytes.length>4*1024*1024)throw new IOException("Subtitle exceeds 4 MB");if(token!=generation)return;File dir=new File(session.context.getFilesDir(),"channel-subtitles");dir.mkdirs();File raw=new File(dir,"auto-"+token+".part"),target=new File(dir,MediaCache.key(movie.cacheIdentity())+"-auto.srt");SmallFileIO.write(raw,bytes);SmallFileIO.copySubtitle(raw,target);raw.delete();String finalName=name,mime=PlayerActivity.subtitleMime(name),finalSource=source;session.ui.post(()->{if(token!=generation||session.movie==null||!session.movie.cacheIdentity().equals(movie.cacheIdentity()))return;session.subtitlePath=target.getAbsolutePath();session.subtitleName=finalName;session.subtitleType=mime;session.subtitleStatus=finalSource+" · "+finalName;session.notifyChanged();});}catch(Exception e){if(token==generation)session.subtitleStatus="Auto subtitles: "+e.getMessage();}finally{session.notifyChanged();}});}
 static final class Packed{final String name;final byte[] bytes;Packed(String n,byte[] b){name=n;bytes=b;}}
 static Packed unpack(byte[] archive,Movie movie,String outer)throws Exception{Packed best=null;int rank=-1,count=0,total=0;MediaTitle wanted=MediaTitle.parse(movie.title);try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(archive))){ZipEntry e;while((e=zip.getNextEntry())!=null){if(++count>1000)throw new IOException("Too many subtitle entries");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=zip.read(buffer))!=-1){total+=n;if(total>32*1024*1024||out.size()+n>4*1024*1024)throw new IOException("Subtitle pack too large");out.write(buffer,0,n);}if(e.isDirectory()||!subtitle(e.getName()))continue;String base=new File(e.getName()).getName();int score=score(movie,base,"");MediaTitle inner=title(base);if(score<0&&pack(movie,outer)&&wanted.episodic()&&inner.episodic()&&inner.season==wanted.season&&inner.episode==wanted.episode)score=70;if(score>rank){rank=score;best=new Packed(base,out.toByteArray());}}}return best;}
}
